export const MegaNetPharmacyInteractionAd: React.FC<{debug?: string}> = ({debug = ''}) => {
  const frame = useCurrentFrame();
  return (
    <DebugContext.Provider value={debug}>
      <AbsoluteFill style={{fontFamily: FONT, backgroundColor: '#EAF3FF'}}>
        {debug === 'notext' && <style>{'*{color:transparent!important;-webkit-text-fill-color:transparent!important;text-shadow:none!important}'}</style>}
        <Sequence from={LEAD} layout="none">
          <Audio src={staticFile('voiceover-pharmacy.mp3')} />
        </Sequence>
        {/* everything visual is frozen once the voice has ended: the last 2s are one held frame */}
        <Freeze frame={Math.min(frame, FREEZE)}>
          <Backgrounds />
          <SceneFrame i={0}>{(l) => <Scene0 l={l} />}</SceneFrame>
          <SceneFrame i={1}>{(l) => <Scene1 l={l} />}</SceneFrame>
          <SceneFrame i={2}>{(l, f) => <Scene2 l={l} f={f} />}</SceneFrame>
          <SceneFrame i={3}>{(l, f) => <Scene3 l={l} f={f} />}</SceneFrame>
          <Layer kind="content">
            <Header />
          </Layer>
          <Captions />
          <Violate />
          <CaptionViolation />
        </Freeze>
        {debug === 'audit' && <AuditProbe />}
      </AbsoluteFill>
    </DebugContext.Provider>
  );
};
